import { stegaClean } from 'next-sanity'
import { Image, type ImageProps } from 'next-sanity/image'

import { urlFor } from '@/lib/sanity/image'
import type { SanityImageData } from '@/types/sanity'

type Props = Omit<ImageProps, 'src' | 'alt' | 'width' | 'height'> & {
  image: SanityImageData | null | undefined
  /** Overrides the editor-supplied alt text. */
  alt?: string
} & (
    | { fill: true; width?: never; height?: never }
    | { fill?: false; width?: number; height?: number }
  )

/**
 * next/image wrapper for Sanity assets. URLs are generated by the Sanity CDN
 * (via next-sanity's loader), not the Next.js optimizer; crop, hotspot,
 * intrinsic dimensions and LQIP blur placeholders are applied automatically.
 */
export function SanityImage({ image, alt, width, height, fill, ...props }: Props) {
  // Asset metadata is never meant to carry Visual Editing markers.
  const clean = stegaClean(image)
  const asset = clean?.asset
  if (!asset) return null

  const source = {
    asset: { _ref: asset._id },
    crop: clean.crop ?? undefined,
    hotspot: clean.hotspot ?? undefined,
  }
  const dims = asset.metadata?.dimensions
  const lqip = asset.metadata?.lqip ?? undefined

  // When only one side is given, derive the other from the asset's aspect ratio.
  const w = fill
    ? undefined
    : (width ?? (height && dims ? Math.round((height * dims.width) / dims.height) : dims?.width))
  const h = fill
    ? undefined
    : (height ?? (w && dims ? Math.round((w * dims.height) / dims.width) : dims?.height))

  const builder = urlFor(source)
  const src = (w && h ? builder.width(w).height(h).fit('crop') : builder).url()

  return (
    <Image
      {...props}
      src={src}
      alt={alt ?? clean.alt ?? ''}
      {...(fill ? { fill: true } : { width: w, height: h })}
      placeholder={lqip ? 'blur' : 'empty'}
      blurDataURL={lqip}
    />
  )
}
